create extension if not exists "pgcrypto";
create table public.users (id uuid primary key references auth.users(id) on delete cascade,spotify_id text unique not null,display_name text,avatar text,created_at timestamptz not null default now());
create table public.mixtapes (id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users(id) on delete cascade,title text not null,description text,cover_image text,recipient text,mood text,published boolean not null default false,created_at timestamptz not null default now());
create table public.tracks (id uuid primary key default gen_random_uuid(),mixtape_id uuid not null references public.mixtapes(id) on delete cascade,spotify_track_id text not null,title text not null,artist text not null,image text,note text,position jsonb not null default '{"x":0,"y":0}'::jsonb,sort_order integer not null default 0,created_at timestamptz not null default now());
alter table public.users enable row level security;alter table public.mixtapes enable row level security;alter table public.tracks enable row level security;
create policy "Users read own profile" on public.users for select using (auth.uid()=id);create policy "Users update own profile" on public.users for update using (auth.uid()=id);
create policy "Owners manage mixtapes" on public.mixtapes for all using (auth.uid()=user_id) with check (auth.uid()=user_id);create policy "Published mixtapes are public" on public.mixtapes for select using (published=true);
create policy "Owners manage tracks" on public.tracks for all using (exists(select 1 from public.mixtapes m where m.id=mixtape_id and m.user_id=auth.uid())) with check (exists(select 1 from public.mixtapes m where m.id=mixtape_id and m.user_id=auth.uid()));create policy "Published tracks are public" on public.tracks for select using (exists(select 1 from public.mixtapes m where m.id=mixtape_id and m.published=true));
create index tracks_mixtape_sort_idx on public.tracks(mixtape_id,sort_order);
